export type Cell = readonly [number, number]; // [row, col]
export type Grid = { rows: number; cols: number; live: Set<string> };

const key = (r: number, c: number): string => `${r},${c}`;
const parseKey = (k: string): Cell => {
  const [r, c] = k.split(",").map(Number);
  return [r, c];
};

export function makeGrid(rows: number, cols: number, cells: Cell[] = []): Grid {
  const live = new Set<string>();
  for (const [r, c] of cells) live.add(key(mod(r, rows), mod(c, cols)));
  return { rows, cols, live };
}

function mod(n: number, m: number): number {
  return ((n % m) + m) % m;
}

/** Neighbors on a toroidal (wrap-around) grid. */
function neighbors([r, c]: Cell, g: Grid): Cell[] {
  const out: Cell[] = [];
  for (let dr = -1; dr <= 1; dr++) {
    for (let dc = -1; dc <= 1; dc++) {
      if (dr === 0 && dc === 0) continue;
      out.push([mod(r + dr, g.rows), mod(c + dc, g.cols)]);
    }
  }
  return out;
}

/** Advance the grid by one generation (B3/S23). */
export function step(g: Grid): Grid {
  const counts = new Map<string, number>();
  for (const k of g.live) {
    for (const n of neighbors(parseKey(k), g)) {
      const nk = key(n[0], n[1]);
      counts.set(nk, (counts.get(nk) ?? 0) + 1);
    }
  }
  const live = new Set<string>();
  const all = new Set([...g.live, ...counts.keys()]);
  for (const k of all) {
    const n = counts.get(k) ?? 0;
    const alive = g.live.has(k);
    if ((alive && (n === 2 || n === 3)) || (!alive && n === 3)) live.add(k);
  }
  return { rows: g.rows, cols: g.cols, live };
}

export function run(g: Grid, generations: number): Grid {
  let cur = g;
  for (let i = 0; i < generations; i++) cur = step(cur);
  return cur;
}

export function population(g: Grid): number {
  return g.live.size;
}

/** Live cells as sorted [row, col] tuples. */
export function liveCells(g: Grid): Cell[] {
  return [...g.live]
    .map(parseKey)
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);
}

/** Translate every live cell by (dr, dc), wrapping toroidally. */
export function translate(g: Grid, dr: number, dc: number): Set<string> {
  const out = new Set<string>();
  for (const k of g.live) {
    const [r, c] = parseKey(k);
    out.add(key(mod(r + dr, g.rows), mod(c + dc, g.cols)));
  }
  return out;
}

