import { describe, expect, it } from "vitest";
import { liveCells, makeGrid, population, run, step, translate } from "../src/game";

const blinkerCells: [number, number][] = [
  [5, 4],
  [5, 5],
  [5, 6],
];

const blockCells: [number, number][] = [
  [3, 3],
  [3, 4],
  [4, 3],
  [4, 4],
];

// Glider pointing down-right, top-left corner at (2,2)
const gliderCells: [number, number][] = [
  [2, 3],
  [3, 4],
  [4, 2],
  [4, 3],
  [4, 4],
];

describe("Game of Life", () => {
  it("blinker has period 2", () => {
    const g = makeGrid(10, 10, blinkerCells);
    const gen1 = step(g);
    const gen2 = step(gen1);
    expect(gen1.live).not.toEqual(g.live); // vertical orientation differs
    expect(gen2.live).toEqual(g.live); // back to original
  });

  it("glider translates by (1,1) after 4 generations on a 20x20 torus", () => {
    const g = makeGrid(20, 20, gliderCells);
    const after4 = run(g, 4);
    const expected = translate(g, 1, 1);
    expect(after4.live).toEqual(expected);
    // sanity: shape actually moved
    expect(after4.live).not.toEqual(g.live);
  });

  it("block is a still life over 10 generations", () => {
    const g = makeGrid(10, 10, blockCells);
    const after = run(g, 10);
    expect(liveCells(after)).toEqual(liveCells(g));
  });

  it("glider population stays 5 throughout", () => {
    let g = makeGrid(20, 20, gliderCells);
    for (let gen = 0; gen <= 8; gen++) {
      expect(population(g)).toBe(5);
      g = step(g);
    }
  });
});

